StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			Analog Input Simple                                                                                                                                                                                                                                                                         
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0				2026-02-18		William Veim			Initial release
//	1.1.0				2025-03-19		William Veim			Removed input for SMS process value
//	2.0.0				2025-04-20		William Veim			Rework - Moved modbus configuration to FB 
//
//===============================================================================================================================
//
//		NB!
//		Modbus configuration is only unsed when block is set to oxygen measurement.
//		If temperature is selected, using same registers as oxygen block reading (so in ordrer to use temperature, oxygen value must be read)
//
//===============================================================================================================================

(*************************************************************************
*	CONGIURING MODBUS REQUEST
*************************************************************************)
IF NOT Cfg_MeasurementConfig THEN //Oxygen measurement
	
	//FIRMWARE DATA
	Inp_Request[Cfg_Request_StartPos+0].Enable:=TRUE;
	Inp_Request[Cfg_Request_StartPos+0].FunctionCode:=Fn03_ReadHoldingRegisters;
	Inp_Request[Cfg_Request_StartPos+0].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+0].Read.Count:=16;
	Inp_Request[Cfg_Request_StartPos+0].Read.StartAddressLocal:=Cfg_HoldingReg_StartPos+0;
	Inp_Request[Cfg_Request_StartPos+0].Read.StartAddressRemote:=1023;

	//SERIAL NUMBER
	Inp_Request[Cfg_Request_StartPos+1].Enable:=TRUE;
	Inp_Request[Cfg_Request_StartPos+1].FunctionCode:=Fn03_ReadHoldingRegisters;
	Inp_Request[Cfg_Request_StartPos+1].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+1].Read.Count:=8;
	Inp_Request[Cfg_Request_StartPos+1].Read.StartAddressLocal:=Cfg_HoldingReg_StartPos+16;
	Inp_Request[Cfg_Request_StartPos+1].Read.StartAddressRemote:=1063;

	//OXYGEN VALUE DATA
	Inp_Request[Cfg_Request_StartPos+2].Enable:=TRUE;
	Inp_Request[Cfg_Request_StartPos+2].FunctionCode:=Fn03_ReadHoldingRegisters;
	Inp_Request[Cfg_Request_StartPos+2].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+2].Read.Count:=6;
	Inp_Request[Cfg_Request_StartPos+2].Read.StartAddressLocal:=Cfg_HoldingReg_StartPos+24;
	Inp_Request[Cfg_Request_StartPos+2].Read.StartAddressRemote:=2089;

	//TEMPERATURE VALUE
	Inp_Request[Cfg_Request_StartPos+3].Enable:=TRUE;
	Inp_Request[Cfg_Request_StartPos+3].FunctionCode:=Fn03_ReadHoldingRegisters;
	Inp_Request[Cfg_Request_StartPos+3].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+3].Read.Count:=2;
	Inp_Request[Cfg_Request_StartPos+3].Read.StartAddressLocal:=Cfg_HoldingReg_StartPos+30;
	Inp_Request[Cfg_Request_StartPos+3].Read.StartAddressRemote:=2411;

	//READ CALIBRATION VALUES
	Inp_Request[Cfg_Request_StartPos+4].Enable:=TRUE;
	Inp_Request[Cfg_Request_StartPos+4].FunctionCode:=Fn03_ReadHoldingRegisters;
	Inp_Request[Cfg_Request_StartPos+4].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+4].Read.Count:=2;
	Inp_Request[Cfg_Request_StartPos+4].Read.StartAddressLocal:=Cfg_HoldingReg_StartPos+32;
	Inp_Request[Cfg_Request_StartPos+4].Read.StartAddressRemote:=5193;

	//WRITE CALIBRATION VALUES
	Inp_Request[Cfg_Request_StartPos+5].Enable:=Wrk_Calibrate;
	Inp_Request[Cfg_Request_StartPos+5].FunctionCode:=Fn16_WriteMultipleRegisters;
	Inp_Request[Cfg_Request_StartPos+5].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+5].Write.Count:=2;
	Inp_Request[Cfg_Request_StartPos+5].Write.StartAddressLocal:=Cfg_HoldingReg_StartPos+34;
	Inp_Request[Cfg_Request_StartPos+5].Write.StartAddressRemote:=5527;

	//WRITE SAMPLING TIME
	Inp_Request[Cfg_Request_StartPos+6].Enable:=TRUE;
	Inp_Request[Cfg_Request_StartPos+6].FunctionCode:=Fn16_WriteMultipleRegisters;
	Inp_Request[Cfg_Request_StartPos+6].NodeAdr:=Cfg_NodeAdr;
	Inp_Request[Cfg_Request_StartPos+6].Write.Count:=2;
	Inp_Request[Cfg_Request_StartPos+6].Write.StartAddressLocal:=Cfg_HoldingReg_StartPos+36;
	Inp_Request[Cfg_Request_StartPos+6].Write.StartAddressRemote:=3499;
	
END_IF;

(*************************************************************************
 *	VARIABLE CONTROL
 *************************************************************************)

Ext_AnalogValue.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
FB_AnalogInput_Logic.Cfg_ValueType:=				TRUE; //INPUT VALUE TO LOGIC BLOCK IS PROCESS VALUE
FB_AnalogInput_Logic.Cfg_CalibrationEnable:=	TRUE;

IF Ext_AnalogValue.EXT_Operator.Calibrate_Upper THEN
	Wrk_Calibrate:=TRUE;
	Ext_AnalogValue.EXT_Operator.Calibrate_Upper:=FALSE;
ELSIF Inp_Request[Cfg_Request_StartPos+5].Status.Success AND NOT Inp_Request[Cfg_Request_StartPos+5].Status.Error THEN
	Wrk_Calibrate:=FALSE;
END_IF;

//COMMUNICATION STATUS
Wrk_ComState:= TRUE;

IF (Inp_Request[Cfg_Request_StartPos+0].Enable AND Inp_Request[Cfg_Request_StartPos+0].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+1].Enable AND Inp_Request[Cfg_Request_StartPos+1].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+2].Enable AND Inp_Request[Cfg_Request_StartPos+2].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+3].Enable AND Inp_Request[Cfg_Request_StartPos+3].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+4].Enable AND Inp_Request[Cfg_Request_StartPos+4].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+5].Enable AND Inp_Request[Cfg_Request_StartPos+5].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+6].Enable AND Inp_Request[Cfg_Request_StartPos+6].Status.Error)
	OR (Inp_Request[Cfg_Request_StartPos+7].Enable AND Inp_Request[Cfg_Request_StartPos+7].Status.Error) THEN
	
Wrk_ComState:=FALSE;

END_IF;

(*************************************************************************
 *	PARSING DATA
 *************************************************************************)

//PARSING FIRMWARE DATE
Wrk_ByteArry[0]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+0]);
Wrk_ByteArry[1]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+0],8));
Wrk_ByteArry[2]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+1]);
Wrk_ByteArry[3]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+1],8));
Wrk_ByteArry[4]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+2]);
Wrk_ByteArry[5]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+2],8));
Wrk_ByteArry[6]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+3]);
Wrk_ByteArry[7]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+3],8));
Wrk_ByteArry[8]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+4]);
Wrk_ByteArry[9]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+4],8));
Wrk_ByteArry[10]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+5]);
Wrk_ByteArry[11]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+5],8));
Wrk_ByteArry[12]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+6]);
Wrk_ByteArry[13]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+6],8));
Wrk_ByteArry[14]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+7]);
Wrk_ByteArry[15]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+7],8));

Wrk_FirmwareDate :=AryToString(In:=Wrk_ByteArry[0], Size:=16);

//PARSING FIRMWARE VERSION
Wrk_ByteArry[0]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+8]);
Wrk_ByteArry[1]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+8],8));
Wrk_ByteArry[2]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+9]);
Wrk_ByteArry[3]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+9],8));
Wrk_ByteArry[4]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+10]);
Wrk_ByteArry[5]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+10],8));
Wrk_ByteArry[6]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+11]);
Wrk_ByteArry[7]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+11],8));
Wrk_ByteArry[8]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+12]);
Wrk_ByteArry[9]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+12],8));
Wrk_ByteArry[10]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+13]);
Wrk_ByteArry[11]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+13],8));
Wrk_ByteArry[12]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+14]);
Wrk_ByteArry[13]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+14],8));
Wrk_ByteArry[14]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+15]);
Wrk_ByteArry[15]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+15],8));

Wrk_FirmwareVersion:=AryToString(In:=Wrk_ByteArry[0], Size:=16);

//PARSING SERIAL NUMBER
Wrk_ByteArry[0]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+16]);
Wrk_ByteArry[1]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+16],8));
Wrk_ByteArry[2]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+17]);
Wrk_ByteArry[3]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+17],8));
Wrk_ByteArry[4]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+18]);
Wrk_ByteArry[5]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+18],8));
Wrk_ByteArry[6]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+19]);
Wrk_ByteArry[7]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+19],8));
Wrk_ByteArry[8]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+20]);
Wrk_ByteArry[9]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+20],8));
Wrk_ByteArry[10]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+21]);
Wrk_ByteArry[11]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+21],8));
Wrk_ByteArry[12]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+22]);
Wrk_ByteArry[13]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+22],8));
Wrk_ByteArry[14]:=WORD_TO_BYTE(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+23]);
Wrk_ByteArry[15]:=WORD_TO_BYTE(SHR(Inp_HoldingRegister[Cfg_HoldingReg_StartPos+23],8));

Wrk_SerialNumber:=AryToString(In:=Wrk_ByteArry[0], Size:=16);


//PARSING OXYGEN UNIT
Wrk_DWORD.Wrd[0]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+24];
Wrk_DWORD.Wrd[1]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+25];

CASE DWORD_TO_UDINT(Wrk_DWORD.DWrd) OF
	
	16#10:
		Wrk_OxygenValue_Unit:= '% vol';
	
	16#20:
		Wrk_OxygenValue_Unit:= '% a.s.';
		
	16#40:
		Wrk_OxygenValue_Unit:= 'ppb';
	
	16#80:
		Wrk_OxygenValue_Unit:= 'ppm';
		
	16#80000000:
		Wrk_OxygenValue_Unit:= 'Torr';
		
	16#04000000:
		Wrk_OxygenValue_Unit:= 'µmol/L';
		
	16#20000000:
		Wrk_OxygenValue_Unit:= 'hPa';
		
	16#40000000:
		Wrk_OxygenValue_Unit:= 'ppm gas';
	
END_CASE;	
	
//PARSING OXYGEN VALUE
Wrk_DWORD.Wrd[0]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+26];
Wrk_DWORD.Wrd[1]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+27];

Wrk_OxygenValue:= CopyDwordToReal(Wrk_DWORD.DWrd);

//PARSING ERROR CODE
Wrk_DWORD.Wrd[0]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+28];
Wrk_DWORD.Wrd[1]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+29];

IF TestABit(In:=Wrk_DWORD.DWrd, Pos:=0) THEN
	Wrk_ActiveError:= '0 - Reference channel overflow';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=1) THEN
	Wrk_ActiveError:= '1 - Temperature too high';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=2) THEN
	Wrk_ActiveError:= '2 - Reference photo detector overflow A';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=3) THEN
	Wrk_ActiveError:= '3 - Signal channel overflow';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=4) THEN
	Wrk_ActiveError:= '4 - Reserved (Unknown)';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=5) THEN
	Wrk_ActiveError:= '5 - Reserved (Unknown)';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=6) THEN
	Wrk_ActiveError:= '6 - Amplitude too low';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=7) THEN
	Wrk_ActiveError:= '7 - Pulse counter overflow';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=8) THEN
	Wrk_ActiveError:= '8 -  Reference amplitude out of range';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=9) THEN
	Wrk_ActiveError:= '9 -  Signal photo detector overflow';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=10) THEN
	Wrk_ActiveError:= '10 -  Signal photo detector overflow';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=11) THEN
	Wrk_ActiveError:= '11 -  Memory write error detected';
ELSIF TestABit(In:=Wrk_DWORD.DWrd, Pos:=11) THEN
	Wrk_ActiveError:= '12 -  PME timeout';
END_IF;

//PARSING TEMPERATURE DATA
Wrk_TemperatureValue_Unit:='℃';

Wrk_DWORD.Wrd[0]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+30];
Wrk_DWORD.Wrd[1]:=Inp_HoldingRegister[Cfg_HoldingReg_StartPos+31];

Wrk_TemperatureValue:= CopyDwordToReal(Wrk_DWORD.DWrd);

IF NOT Cfg_MeasurementConfig THEN
	
	//UPDATING CALIBRATION VALUE
	Wrk_DWORD.DWrd:=CopyRealToDword(In:=Ext_AnalogValue.EXT_Operator.CalibrateValue_Upper);

	Inp_HoldingRegister[Cfg_HoldingReg_StartPos+34]:=Wrk_DWORD.Wrd[0];
	Inp_HoldingRegister[Cfg_HoldingReg_StartPos+35]:=Wrk_DWORD.Wrd[1];

	//UPDATING SAMPLING RATE
	Wrk_DWORD.DWrd:=CopyNumToDword(In:=LINT_TO_DINT(TimeToSec(Cfg_SamplingInterval)));

	Inp_HoldingRegister[Cfg_HoldingReg_StartPos+36]:=Wrk_DWORD.Wrd[0];
	Inp_HoldingRegister[Cfg_HoldingReg_StartPos+37]:=Wrk_DWORD.Wrd[1];
	
END_IF;

(*************************************************************************
 *	BLOCK SPESIFIC PARAMETERS
 *************************************************************************)

FB_AnalogInput_Logic.Cfg_ValueType:=TRUE; //INPUT VALUE TO LOGIC BLOCK IS PROCESS VALUE

(*************************************************************************
 *	UPDATE INPUT PARAMETERS
 *************************************************************************)

FB_AnalogInput_Logic.Inp_AlmSuppress:=				Inp_AlmSuppress;
FB_AnalogInput_Logic.Inp_AlmSuppressDesc:=		Inp_AlmSuppressDesc;
FB_AnalogInput_Logic.Inp_ModuleFault:=				NOT Wrk_ComState;

IF NOT Cfg_MeasurementConfig THEN //READ OXYGEN VALUE
	FB_AnalogInput_Logic.Inp_Value:=							Wrk_OxygenValue;
	FB_AnalogInput_Logic.Cfg_ProcessValue_Unit := 	Wrk_OxygenValue_Unit;
ELSE //READ TEMPERATURE VALUE
	FB_AnalogInput_Logic.Inp_Value:=							Wrk_TemperatureValue;
	FB_AnalogInput_Logic.Cfg_ProcessValue_Unit := 	Wrk_TemperatureValue_Unit;
END_IF;

(*************************************************************************
 *	UPDATE CONFIG PARAMETERS
 *************************************************************************)
 
FB_AnalogInput_Logic.Cfg_SignalValue_Y0:=							0; //NOT IN USE
FB_AnalogInput_Logic.Cfg_SignalValue_Y1:=							0; //NOT IN USE
FB_AnalogInput_Logic.Cfg_SignalValue_Unit:=						''; //NOT IN USE
FB_AnalogInput_Logic.Cfg_ControlCabinet:=							Cfg_ConnCabinet;
FB_AnalogInput_Logic.Cfg_ControllerTAG:=							Cfg_ControllerName;
FB_AnalogInput_Logic.Cfg_ProcessTAG:=								Cfg_ProcessTAG;

(*************************************************************************
 *	STATISTICS
 * (Asuming sensor has been changed, if serial number has changed)
 *************************************************************************)
	
IF Wrk_SerialNumber <> Wrk_SerialNum_Sample AND Wrk_ComState THEN
	FB_AnalogInput_Logic.Inp_RstOperatingTime:= TRUE;
	Wrk_SerialNum_Sample:= Wrk_SerialNumber;
END_IF;

(*************************************************************************
 *	UPDATING STATE CONTROL PARAMTERS
 *************************************************************************)
 
 //STATE 1 - Locked to "Critical high limit"
 //STATE 2 - Locked to "Pre high limit"
 //STATE 3 - Locked to "Pre low limit"
 //STATE 4 - Locked to "Critical low limit"
 //STATE 5 - Locked to "Process value out of range"
 //STATE 6 - Locked to "Input module fault"
 //STATE 7 - Locked to "Value stuck"
 //STATE 8 - Locked to "Calibration fault"
 //STATE 9 - Locked to "Unstable value"
 
FB_AnalogInput_Logic.Cfg_State10_InUse:= FALSE; //NOT IN USE

FB_AnalogInput_Logic.Cfg_State11_InUse:= FALSE; //NOT IN USE

FB_AnalogInput_Logic.Cfg_State12_InUse:= FALSE;  //NOT IN USE

(*************************************************************************
 *	EXCECUTING LOGICK BLOCK
 *************************************************************************)
 
FB_AnalogInput_Logic(ENS:=TRUE, 
										Ext_AnalogValue:=	Ext_AnalogValue, 
										Int_Alarm:=				Int_Alarm); 

(*************************************************************************
 *	UPDATING FB OUTPUT
 *************************************************************************)
 
Sts_Alarm:= 								FB_AnalogInput_Logic.Sts_AlarmTriggered;
Out_ProcessValue:= 				Ext_AnalogValue.EXT_Operator.ProcessValue;
Out_ProcessValue_Percent := 	Ext_AnalogValue.EXT_Operator.ProcessValue_Percent;
Out_FirmwareVersion:= 			Wrk_FirmwareVersion;
Out_FirmwareDate:=				Wrk_FirmwareDate;
Out_SerialNumber:=				Wrk_SerialNumber;
